SELECT j->>'slug',j->>'title',j->>'level',(j->>'order')::integer,j->>'summary',j->>'guidance',ARRAY(SELECT jsonb_array_elements_text(j->'learningGoals')),j->'rules',ARRAY(SELECT jsonb_array_elements_text(j->'tips')),'seed','{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-ed-ing-adjectives"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment.","contentHash":"96c6d65cc82b241ec16c30e21e2355867131e9c8c0230502f0315bae0cab7edb","sources":[{"id":"bc-ed-ing-adjectives","title":"Adjectives ending in -ed and -ing","publisher":"British Council","url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/adjectives-ending-ed-ing","use":"Guidance reference only; original contexts and exercises, no publisher question text reproduced","accessed":"2026-09-13"}]}'::jsonb FROM (SELECT '{"slug":"ed-ing-adjectives","title":"Adjectives ending in -ed and -ing","level":"A2","order":18,"summary":"Distinguish an experienced feeling from something that causes that feeling.","learningGoals":["The experienced feeling","The cause of the feeling","Connect cause and effect"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"The experienced feeling","explanation":"In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer.","examples":["The climbers felt exhausted.","The children seemed delighted."]},{"title":"The cause of the feeling","explanation":"The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut.","examples":["The climb was exhausting.","An entertaining storyteller can hold our attention."]},{"title":"Connect cause and effect","explanation":"Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles.","examples":["A confusing instruction leaves a reader confused.","An exciting event leaves spectators excited."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-ed-ing-adjectives"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."}}'::jsonb j) payload
